python3 << 'EOF'
import re

with open('/app/resources/treasury_bulletin_1980_05_page_41.txt', 'r') as f:
    content = f.read()

all_td = re.findall(r'<td>([^<]*)</td>', content)

def clean_value(val):
    val = re.sub(r'\s+\d+/$', '', val)
    val = re.sub(r'r$', '', val)
    return val

def is_row_header(val):
    if re.match(r'^\d{4}$', val):
        return True
    if re.match(r'^\d{4}-[A-Za-z.]+$', val):
        return True
    if val in ['T.Q.', 'T.O.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.']:
        return True
    return False

row_headers = []
data_values = []

for i, val in enumerate(all_td):
    cleaned = clean_value(val)
    if cleaned == '*':
        continue
    if is_row_header(cleaned):
        row_headers.append(cleaned)
    else:
        data_values.append(cleaned)

print("=== Row headers detected ===")
for h in row_headers:
    print(f"  '{h}'")

print(f"\nTotal row headers: {len(row_headers)}")
print(f"Total data values: {len(data_values)}")

# Now count data values starting with '1'
count = 0
for val in data_values:
    clean = val.replace(',', '')
    if clean and clean[0] == '1':
        count += 1

print(f"\n=== Data values starting with '1': {count} ===")
EOF
